using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
using Vortice.Direct3D11;
using Vortice.DXGI;

namespace YuCap;

/// <summary>One pass of an Anime4K CNN (wiring generated by tools/a4k_gen.py into A4kModels.g.cs).</summary>
internal sealed record A4kPassInfo(string Entry, int[] Inputs, int Output);

/// <summary>
/// 「くっきり（アニメ・イラスト向け）」: the Anime4K CNN upscaler (bloc97, MIT; third_party/Anime4K) as a scaling quality.
/// The CNN doubles the picture (x2) by a stack of small convolutions into float16 textures and a depth-to-space pass that
/// adds the result onto the bilinear-enlarged picture; what follows (exact size: RCAS only, else bilinear / EASU, then RCAS)
/// is in <see cref="D3DRenderer"/>.Compose. The result is cached per picture: the CNN runs once per new frame.
/// </summary>
internal sealed partial class D3DRenderer
{
    // ---- settings (static: shared by the live pipeline and the test code) ----
    /// <summary>Which network: 'S' small, 'M' medium (the default), 'L' large. See A4kModels / the README.</summary>
    public static char A4kVariantLetter = 'M';
    /// <summary>float16 intermediate textures (false = float32; the equivalence check uses float32 to show the port is exact).</summary>
    public static bool A4kHalf = true;
    /// <summary>After the CNN, resample to a different destination size with FSR EASU instead of bilinear (both are followed by RCAS).</summary>
    public static bool A4kUseEasu = true;
    /// <summary>Test hook: never reuse the cached CNN result (so a benchmark loop really runs it).</summary>
    public static bool A4kNoCache;
    /// <summary>If the CNN cannot run (shader or memory), draw with FSR instead.</summary>
    private const bool A4kFallbackFsr = true;
    /// <summary>A second x2 is run when the destination is at least this many times larger than the (prescaled) source.</summary>
    public static double A4kSecondStageRatio = 2.99;
    /// <summary>The second x2 only runs when the CNN's estimated GPU time (both stages) stays within this many milliseconds, so that it fits next to
    /// everything else in one 144 Hz refresh (6.94 ms). Measured on an RTX 4060: M costs about 0.8 ms per megapixel of input per stage (S 0.4, L 1.2);
    /// a 720p picture would need 3.7 ms, a 480p one 1.2 ms. Memory is no issue below that (the textures of a stage-2 input of 3 Mpixel are ~0.2 GB).</summary>
    public static double A4kBudgetMs = 3.0;
    private static double A4kMsPerMegapixel(char v) => v switch { 'S' => 0.4, 'L' => 1.2, _ => 0.8 };

    internal readonly record struct A4kKey(long Ver, int PreH, int PreFilter, int PreIter, float PreClamp, char Variant, int Stages, bool Half);

    private sealed class A4kTex
    {
        public ID3D11Texture2D Tex = null!;
        public ID3D11ShaderResourceView Srv = null!;
        public ID3D11RenderTargetView Rtv = null!;
        public Size Size;
        public Format Fmt;
        public void Dispose() { Rtv?.Dispose(); Srv?.Dispose(); Tex?.Dispose(); }
    }

    private long _orientedVer;
    private A4kKey _a4kKey;
    private bool _a4kHaveKey;
    private A4kTex? _a4kResult;
    private readonly List<A4kTex?>[] _a4kInter = { new(), new() };   // per stage: the convolution textures
    private readonly A4kTex?[] _a4kOut = new A4kTex?[2];             // per stage: the x2 picture
    private ID3D11PixelShader[]? _a4kPs;
    private char _a4kPsLetter;
    private ID3D11Buffer? _cbA4k;
    private bool _a4kBroken;

    /// <summary>True when the CNN shaders compile (first call compiles; ~0.3 s once per process).</summary>
    public bool A4kAvailable
    {
        get
        {
            if (_a4kBroken) return false;
            try { return EnsureA4kShaders(); }
            catch (Exception ex)
            {
                _a4kBroken = true;
                Log.Info("D3D: Anime4K unavailable - " + ex.Message.Split('\n')[0]);
                return false;
            }
        }
    }

    private static A4kPassInfo[] PassesOf(char v) => v switch { 'S' => A4kModels.PassesS, 'L' => A4kModels.PassesL, _ => A4kModels.PassesM };
    private static int TexturesOf(char v) => v switch { 'S' => A4kModels.TexturesS, 'L' => A4kModels.TexturesL, _ => A4kModels.TexturesM };

    private bool EnsureA4kShaders()
    {
        char v = A4kVariantLetter;
        if (_a4kPs != null && _a4kPsLetter == v) return true;
        byte[][] code = D3DShaders.GetA4k(v);
        if (_a4kPs != null) foreach (var p in _a4kPs) p.Dispose();
        _a4kPs = new ID3D11PixelShader[code.Length];
        for (int i = 0; i < code.Length; i++) _a4kPs[i] = Device.CreatePixelShader(code[i]);
        _a4kPsLetter = v;
        _cbA4k ??= Device.CreateBuffer(new BufferDescription(16, BindFlags.ConstantBuffer, ResourceUsage.Default));
        return true;
    }

    /// <summary>How many x2 stages to run for a picture of <paramref name="src"/> drawn at <paramref name="dst"/>:
    /// 0 when the destination is not larger in both directions (or the shaders are unavailable), 1 normally, 2 from a 3x larger destination
    /// when the second stage's textures fit the budget.</summary>
    private int A4kPlan(Size src, Size dst)
    {
        if (dst.Width <= src.Width || dst.Height <= src.Height || src.Width < 4 || src.Height < 4) return 0;
        if (!A4kAvailable) return 0;
        double ratio = Math.Min((double)dst.Width / src.Width, (double)dst.Height / src.Height);
        if (ratio >= A4kSecondStageRatio)
        {
            double mp = src.Width * (double)src.Height / 1e6;
            if (A4kMsPerMegapixel(A4kVariantLetter) * (mp + 4 * mp) <= A4kBudgetMs) return 2;
        }
        return 1;
    }

    private static Format A4kFormat => A4kHalf ? Format.R16G16B16A16_Float : Format.R32G32B32A32_Float;

    private A4kTex A4kEnsure(ref A4kTex? t, Size sz)
    {
        Format fmt = A4kFormat;
        if (t != null && t.Size == sz && t.Fmt == fmt) return t;
        t?.Dispose();
        var n = new A4kTex { Size = sz, Fmt = fmt };
        n.Tex = Device.CreateTexture2D(new Texture2DDescription
        {
            Width = (uint)sz.Width, Height = (uint)sz.Height, MipLevels = 1, ArraySize = 1,
            Format = fmt, SampleDescription = new SampleDescription(1, 0),
            Usage = ResourceUsage.Default, BindFlags = BindFlags.RenderTarget | BindFlags.ShaderResource,
        });
        n.Srv = Device.CreateShaderResourceView(n.Tex);
        n.Rtv = Device.CreateRenderTargetView(n.Tex);
        t = n;
        return n;
    }

    private void A4kFree()
    {
        foreach (var list in _a4kInter) { foreach (var t in list) t?.Dispose(); list.Clear(); }
        for (int i = 0; i < 2; i++) { _a4kOut[i]?.Dispose(); _a4kOut[i] = null; }
        _a4kResult = null; _a4kHaveKey = false;
        if (_a4kPs != null) { foreach (var p in _a4kPs) p.Dispose(); _a4kPs = null; }
        _cbA4k?.Dispose(); _cbA4k = null;
    }

    /// <summary>Run <paramref name="stages"/> x2 passes on <paramref name="srcSrv"/> (size <paramref name="src"/>); the result lands in _a4kResult.</summary>
    private bool A4kRun(ID3D11ShaderResourceView srcSrv, Size src, int stages, A4kKey key)
    {
        try
        {
            if (!EnsureA4kShaders()) return false;
            ID3D11ShaderResourceView cur = srcSrv;
            Size sz = src;
            A4kTex? outTex = null;
            for (int st = 0; st < stages; st++)
            {
                outTex = A4kStage(cur, sz, st);
                cur = outTex.Srv;
                sz = outTex.Size;
            }
            _a4kResult = outTex;
            _a4kKey = key; _a4kHaveKey = true;
            return true;
        }
        catch (Exception ex)
        {
            Log.Info("D3D: Anime4K pass failed - " + ex.Message.Split('\n')[0]);
            _a4kBroken = true;
            _a4kResult = null; _a4kHaveKey = false;
            return false;
        }
    }

    private A4kTex A4kStage(ID3D11ShaderResourceView input, Size src, int stage)
    {
        A4kPassInfo[] passes = PassesOf(_a4kPsLetter);
        int nTex = TexturesOf(_a4kPsLetter);
        List<A4kTex?> inter = _a4kInter[stage];
        while (inter.Count < nTex) inter.Add(null);
        for (int i = 0; i < nTex; i++) { A4kTex? t = inter[i]; A4kEnsure(ref t, src); inter[i] = t; }
        Size outSize = new(src.Width * 2, src.Height * 2);
        A4kTex outTex = A4kEnsure(ref _a4kOut[stage], outSize);

        WriteCb(_cbA4k!, new uint[] { (uint)src.Width, (uint)src.Height, 0, 0 });
        for (int pi = 0; pi < passes.Length; pi++)
        {
            A4kPassInfo p = passes[pi];
            bool final = p.Output == -2;
            A4kTex target = final ? outTex : inter[p.Output]!;
            SetupTriangle(target.Rtv, new Rectangle(0, 0, target.Size.Width, target.Size.Height));
            Ctx.PSSetShader(_a4kPs![pi]);
            Ctx.PSSetConstantBuffer(0, _cbA4k);
            Ctx.PSSetSampler(0, _linear);
            for (int k = 0; k < p.Inputs.Length; k++)
                Ctx.PSSetShaderResource((uint)k, p.Inputs[k] < 0 ? input : inter[p.Inputs[k]]!.Srv);
            Ctx.Draw(3, 0);
            for (int k = 0; k < p.Inputs.Length; k++) Ctx.PSSetShaderResource((uint)k, null!);
        }
        return outTex;
    }

    // ------------------------------------------------------------------ test / check hooks

    /// <summary>Upload <paramref name="src"/> as the oriented picture, run the CNN for <paramref name="stages"/> stages and read the
    /// result back as float RGBA (0..1 scale, not clamped). Needs no capture and no swap chain.</summary>
    internal float[]? A4kReadRaw(Bitmap src, int stages, out Size size)
    {
        size = Size.Empty;
        lock (FrameLock)
        {
            EnsureOriented(src.Size);
            BitmapData bd = src.LockBits(new Rectangle(Point.Empty, src.Size), ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
            try { Ctx.UpdateSubresource(_oriented!, 0, null, bd.Scan0, (uint)bd.Stride, 0); _orientedVer++; }
            finally { src.UnlockBits(bd); }
            if (!A4kAvailable) return null;
            var key = new A4kKey(_orientedVer, 0, 0, 0, 0f, A4kVariantLetter, stages, A4kHalf);
            if (!A4kRun(_orientedSrv!, src.Size, stages, key)) return null;
            Ctx.OMSetRenderTargets(Array.Empty<ID3D11RenderTargetView>());
            size = _a4kResult!.Size;
            return ReadFloats(_a4kResult);
        }
    }

    private float[] ReadFloats(A4kTex t)
    {
        bool half = t.Fmt == Format.R16G16B16A16_Float;
        using ID3D11Texture2D staging = Device.CreateTexture2D(new Texture2DDescription
        {
            Width = (uint)t.Size.Width, Height = (uint)t.Size.Height, MipLevels = 1, ArraySize = 1,
            Format = t.Fmt, SampleDescription = new SampleDescription(1, 0),
            Usage = ResourceUsage.Staging, BindFlags = BindFlags.None, CPUAccessFlags = CpuAccessFlags.Read,
        });
        Ctx.CopyResource(staging, t.Tex);
        MappedSubresource map = Ctx.Map(staging, 0, MapMode.Read, Vortice.Direct3D11.MapFlags.None);
        var res = new float[t.Size.Width * t.Size.Height * 4];
        try
        {
            int n = t.Size.Width * 4;
            if (half)
            {
                var row = new short[n];
                for (int y = 0; y < t.Size.Height; y++)
                {
                    Marshal.Copy(map.DataPointer + y * (int)map.RowPitch, row, 0, n);
                    for (int i = 0; i < n; i++) res[y * n + i] = (float)BitConverter.Int16BitsToHalf(row[i]);
                }
            }
            else
            {
                for (int y = 0; y < t.Size.Height; y++)
                    Marshal.Copy(map.DataPointer + y * (int)map.RowPitch, res, y * n, n);
            }
        }
        finally { Ctx.Unmap(staging, 0); }
        return res;
    }

    /// <summary>GPU milliseconds of the CNN alone (all stages) for a picture of <paramref name="src"/>; the picture content is whatever
    /// the oriented texture holds (give one with <see cref="RenderFromBitmap"/> first, or the live frame).</summary>
    internal double[] A4kBench(Size src, int stages, int frames)
    {
        if (_oriented == null || !A4kAvailable) return Array.Empty<double>();
        try
        {
            var key = new A4kKey(_orientedVer, 0, 0, 0, 0f, A4kVariantLetter, stages, A4kHalf);
            return TimeGpu(() => A4kRun(_orientedSrv!, src, stages, key), frames);
        }
        finally { Ctx.OMSetRenderTargets(Array.Empty<ID3D11RenderTargetView>()); }
    }

    /// <summary>Test hook: GPU milliseconds of one whole frame (compose at <paramref name="output"/>) for <paramref name="quality"/>,
    /// with the CNN really running every frame (or, with <paramref name="cached"/>, only on the first: the cost of a repeated picture). The oriented picture is the one last given to <see cref="RenderFromBitmap"/>.</summary>
    internal double[] ComposeBench(Size output, ScalingQuality quality, float sharpness, int nativeH, int frames, bool cached = false)
    {
        if (_oriented == null) return Array.Empty<double>();
        Size src = _orientedSize;
        double scale = Math.Min((double)output.Width / src.Width, (double)output.Height / src.Height);
        var dst = new Rectangle(0, 0, Math.Max(1, (int)Math.Round(src.Width * scale)), Math.Max(1, (int)Math.Round(src.Height * scale)));
        Texture2DDescription d = new()
        {
            Width = (uint)output.Width, Height = (uint)output.Height, MipLevels = 1, ArraySize = 1,
            Format = Format.B8G8R8A8_UNorm, SampleDescription = new SampleDescription(1, 0),
            Usage = ResourceUsage.Default, BindFlags = BindFlags.RenderTarget | BindFlags.ShaderResource,
        };
        using ID3D11Texture2D target = Device.CreateTexture2D(d);
        using ID3D11RenderTargetView targetRtv = Device.CreateRenderTargetView(target);
        using ID3D11Texture2D inter = Device.CreateTexture2D(d);
        using ID3D11RenderTargetView interRtv = Device.CreateRenderTargetView(inter);
        using ID3D11ShaderResourceView interSrv = Device.CreateShaderResourceView(inter);
        bool keep = A4kNoCache;
        A4kNoCache = !cached;
        try { return TimeGpu(() => Compose(targetRtv, output, dst, quality, false, sharpness, interRtv, interSrv, nativeH), frames); }
        finally { A4kNoCache = keep; Ctx.OMSetRenderTargets(Array.Empty<ID3D11RenderTargetView>()); }
    }

    internal long OrientedVersion => _orientedVer;

    /// <summary>Test hook: GPU milliseconds per presented frame at <paramref name="output"/>. With only <paramref name="a"/> it is the
    /// plain picture (<paramref name="cached"/>: a repeated frame, the CNN result reused). With <paramref name="b"/> it is a refresh
    /// of the interpolated stream: the in-between picture of the pair is synthesised and composed, every time (the CNN has to run on
    /// each, as the picture is new each refresh).</summary>
    internal double[] QualityBench(Bitmap a, Bitmap? b, Size output, ScalingQuality quality, float sharpness, int nativeH, int frames, bool cached)
    {
        lock (FrameLock)
        {
            if (b == null || !InterpAvailable || a.Size != b.Size)
            {
                EnsureOriented(a.Size);
                BitmapData bd = a.LockBits(new Rectangle(Point.Empty, a.Size), ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
                try { Ctx.UpdateSubresource(_oriented!, 0, null, bd.Scan0, (uint)bd.Stride, 0); _orientedVer++; }
                finally { a.UnlockBits(bd); }
                return ComposeBench(output, quality, sharpness, nativeH, frames, cached);
            }
            Size o = a.Size;
            OriFrame? fa = null, fb = null;
            try
            {
                EnsureOriFrame(ref fa, o); EnsureOriFrame(ref fb, o);
                Upload(fa!, a); Upload(fb!, b);
                EnsureOriented(o);
                _lastAlpha = -1; _curA = _curB = _meA = _meB = 0;
                BuildPyramid(fa!); BuildPyramid(fb!);
                EstimateMotion(fa!, fb!);
                double scale = Math.Min((double)output.Width / o.Width, (double)output.Height / o.Height);
                var dst = new Rectangle(0, 0, Math.Max(1, (int)Math.Round(o.Width * scale)), Math.Max(1, (int)Math.Round(o.Height * scale)));
                Texture2DDescription d = new()
                {
                    Width = (uint)output.Width, Height = (uint)output.Height, MipLevels = 1, ArraySize = 1,
                    Format = Format.B8G8R8A8_UNorm, SampleDescription = new SampleDescription(1, 0),
                    Usage = ResourceUsage.Default, BindFlags = BindFlags.RenderTarget | BindFlags.ShaderResource,
                };
                using ID3D11Texture2D target = Device.CreateTexture2D(d);
                using ID3D11RenderTargetView targetRtv = Device.CreateRenderTargetView(target);
                using ID3D11Texture2D inter = Device.CreateTexture2D(d);
                using ID3D11RenderTargetView interRtv = Device.CreateRenderTargetView(inter);
                using ID3D11ShaderResourceView interSrv = Device.CreateShaderResourceView(inter);
                bool keep = A4kNoCache;
                A4kNoCache = false;   // Synthesize bumps the picture version, so the CNN runs on every iteration anyway
                try
                {
                    return TimeGpu(() =>
                    {
                        Synthesize(fa!, fb!, 0.5f);
                        Compose(targetRtv, output, dst, quality, false, sharpness, interRtv, interSrv, nativeH);
                    }, frames);
                }
                finally { A4kNoCache = keep; Ctx.OMSetRenderTargets(Array.Empty<ID3D11RenderTargetView>()); }
            }
            finally { fa?.Dispose(); fb?.Dispose(); _lastAlpha = -1; _curA = _curB = _meA = _meB = 0; }
        }
    }
}
